#include <iostream>
#include <string>

struct Point {
    int x;
    int y;
};

// Overloading stream insertion for custom type (type-safe output)
std::ostream& operator<<(std::ostream& os, const Point& pt) {
    os << '(' << pt.x << ", " << pt.y << ')';
    return os;
}

// Overloading stream extraction for custom type (type-safe input)
std::istream& operator>>(std::istream& is, Point& pt) {
    is >> pt.x >> pt.y;
    return is;
}

int main() {
    Point p{0, 0};

    // Read user data with compile-time type verification
    if (std::cin >> p) {
        std::cout << "Point successfully read: " << p << '\n';
    }

    return 0;
}

#include <iostream>
#include <type_traits>

int main() {
    // Verify standard typedef aliases for char streams
    static_assert(std::is_same_v<std::istream, std::basic_istream<char>>);
    static_assert(std::is_same_v<std::ostream, std::basic_ostream<char>>);
    static_assert(std::is_same_v<std::iostream, std::basic_iostream<char>>);

    // Verify wide character typedef aliases
    static_assert(std::is_same_v<std::wistream, std::basic_istream<wchar_t>>);
    static_assert(std::is_same_v<std::wostream, std::basic_ostream<wchar_t>>);

    std::cout << "Stream template typedef verification successful!\n";
    std::cout << "Sizes of Unicode character types:\n";
    std::cout << "char: " << sizeof(char) << " byte\n";
    std::cout << "char16_t: " << sizeof(char16_t) << " bytes\n";
    std::cout << "char32_t: " << sizeof(char32_t) << " bytes\n";

    return 0;
}
